-- ==========================================================
-- KDSQ 개발용 샘플 데이터 (회원 26명 + 검사 결과 119건)
-- mock-data/data/members.json, results.json과 같은 내용 (프론트 Mock과 같은 화면을 보기 위함)
--
-- ■ 언제 쓰나: 관리자 회원·결과 목록, 검색·페이지네이션, 대시보드처럼 데이터가 많아야 확인되는 화면
-- ■ data.sql이 아니다: 서버 시작 때 자동 실행되지 않는다. 필요할 때 직접 실행한다
-- ■ 실행 전 조건: 서버를 한 번 실행해 테이블·관리자 계정·설문(data.sql)이 만들어져 있을 것
-- ■ 실행 방법 (둘 중 하나)
--   1) 명령 프롬프트:  cd C:\rookies6\2st_Project\backend\http
--                      mysql -u boot -p --default-character-set=utf8mb4 kdsq_db < sample-data.sql
--      (root 계정을 쓰면 -u root)
--   2) HeidiSQL: kdsq_db 선택 → 파일 → SQL 파일 불러오기 → 이 파일 → 실행(F9)
-- ■ 여러 번 실행해도 된다: 회원은 이메일 기준으로 덮어쓰고, 샘플 회원의 검사 결과는 지우고 다시 넣는다
--   (주의) 샘플 회원(hong 등)으로 직접 만든 검사 결과도 함께 지워진다
--
-- 로그인: 모든 회원 비밀번호 Test1234! (BCrypt 저장), 관리자 admin@kdsq.com은 서버가 자동 등록 (이 파일에 없음)
-- 주요 계정: hong@test.com(이력 6건), kim@test.com(이력 없음), lee@test.com(본인 탈퇴), park@test.com(결과 201번),
--            testuser26@test.com(이력 23건), testuser27@test.com(이력 11건), testuser10@test.com(관리자 비활성화)
-- 결과 id는 Mock과 같게 101~411을 그대로 쓴다 (예: /admin/results/201 = park의 결과)
-- 회원 id는 DB마다 다를 수 있어 이메일로 찾아 연결한다. 관리자가 1번, hong이 2번이면 SecurityUtil 임시 id(2)와도 맞는다
-- ==========================================================

SET NAMES utf8mb4;
START TRANSACTION;

-- 1. 회원 (이메일이 이미 있으면 정보만 덮어씀: 이미 가입한 hong@test.com도 그대로 사용)

ON DUPLICATE KEY UPDATE
 password = VALUES(password), name = VALUES(name), gender = VALUES(gender), birth_year = VALUES(birth_year),
 status = VALUES(status), created_at = VALUES(created_at), updated_at = VALUES(updated_at);

-- 1-1. 비활성 사유 (withdrawn_by 칸은 서버 실행 시 자동 생성): lee = 본인 탈퇴, testuser10 = 관리자 비활성화, 나머지(활성) = NULL
UPDATE members
   SET withdrawn_by = CASE email WHEN 'lee@test.com' THEN 'SELF' WHEN 'testuser10@test.com' THEN 'ADMIN' ELSE NULL END
 WHERE email IN ('hong@test.com', 'kim@test.com', 'lee@test.com', 'park@test.com', 'testuser6@test.com', 'testuser7@test.com', 'testuser8@test.com', 'testuser9@test.com', 'testuser10@test.com', 'testuser11@test.com', 'testuser12@test.com', 'testuser13@test.com', 'testuser14@test.com', 'testuser15@test.com', 'testuser16@test.com', 'testuser17@test.com', 'testuser18@test.com', 'testuser19@test.com', 'testuser20@test.com', 'testuser21@test.com', 'testuser22@test.com', 'testuser23@test.com', 'testuser24@test.com', 'testuser25@test.com', 'testuser26@test.com', 'testuser27@test.com');

-- 2. 기존 샘플 결과 삭제 (다시 실행할 때 중복 방지)
DELETE FROM survey_results
 WHERE id BETWEEN 101 AND 411
    OR member_id IN (SELECT id FROM members WHERE email IN ('hong@test.com', 'kim@test.com', 'lee@test.com', 'park@test.com', 'testuser6@test.com', 'testuser7@test.com', 'testuser8@test.com', 'testuser9@test.com', 'testuser10@test.com', 'testuser11@test.com', 'testuser12@test.com', 'testuser13@test.com', 'testuser14@test.com', 'testuser15@test.com', 'testuser16@test.com', 'testuser17@test.com', 'testuser18@test.com', 'testuser19@test.com', 'testuser20@test.com', 'testuser21@test.com', 'testuser22@test.com', 'testuser23@test.com', 'testuser24@test.com', 'testuser25@test.com', 'testuser26@test.com', 'testuser27@test.com'));

-- 3. 검사 결과 119건 (survey_id 1 = KDSQ-P로 끝난 결과, 2 = KDSQ-C까지 완료, active 0 = 관리자가 삭제한 결과)

COMMIT;

-- 4. 확인 (예상: 회원 26명 + 관리자 1명, 결과 119건 중 활성 109건)
SELECT role, status, COUNT(*) AS cnt FROM members GROUP BY role, status;
SELECT active + 0 AS active, risk_level, COUNT(*) AS cnt FROM survey_results GROUP BY active, risk_level;
